INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, category, image, prayer, virtues, quotes) VALUES 
('charbel', 'São Charbel Makhlouf', 'O Eremita de Annaya', '24 de Julho', 7, 24, '1828', '1898', ARRAY['Pessoas doentes','Paz','Cura','Líbano']::TEXT[], 'Monge maronita libanês', 'Youssef Antoun Makhlouf nasceu numa pequena aldeia no norte do Líbano', 'mystic', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Saint_Charbel_Makhlouf.jpg/440px-Saint_Charbel_Makhlouf.jpg', 'Senhor Deus Todo-Poderoso', ARRAY['Silêncio','Oração','Penitência','Obediência']::TEXT[], ARRAY['O silêncio fala a Deus.','Quem permanece em Deus','Deus permanece nele.']::TEXT[]),
('estanislau', 'Santo Estanislau de Cracóvia', 'Bispo e Mártir', '11 de Abril', 4, 11, '1030', '1079', ARRAY['Polônia','Cracóvia','Estudantes morais']::TEXT[], 'Bispo de Cracóvia e um dos primeiros santos poloneses. Conhecido por sua coragem ao confrontar a imoralidade do Rei Boleslau II', 'Estanislau nasceu em Szczepanów e estudou em Gniezno e Paris antes de ser ordenado sacerdote. Em 1072', 'martyr', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Stanislaus_of_Szczepanow.jpg/440px-Stanislaus_of_Szczepanow.jpg', 'Ó Deus', ARRAY['Coragem','Fidelidade','Zelo Pastoral','Integridade']::TEXT[], ARRAY['Prefiro morrer a trair a lei de Deus.','O dever de um bispo é proteger seu rebanho','mesmo contra reis.']::TEXT[]),
('rita-cassia', 'Santa Rita de Cássia', 'Advogada das Causas Impossíveis', '22 de Maio', 5, 22, '1381', '1457', ARRAY['Causas impossíveis','Casamentos difíceis','Viúvas','Doentes']::TEXT[], '', 'Rita nasceu numa família humilde e', 'mystic', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Santa_Rita_da_Cascia_-_Santuario_Roccaporena.jpg/440px-Santa_Rita_da_Cascia_-_Santuario_Roccaporena.jpg', 'Ó poderosa e gloriosa Santa Rita', ARRAY['Paciência','Perdão','Penitência','Confiança']::TEXT[], ARRAY['Não há nada impossível para Deus.','A paciência é o caminho para a paz.']::TEXT[]),
('nha-chica', 'Beata Nhá Chica', 'A Mãe dos Pobres de Baependi', '14 de Junho', 6, 14, '1808', '1895', ARRAY['Pobres','Baependi','Causas impossíveis']::TEXT[], 'Leiga mineira', 'Francisca de Paula de Jesus', 'mystic', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Nh%C3%A1_Chica.jpg/440px-Nh%C3%A1_Chica.jpg', 'Beata Nhá Chica', ARRAY['Oração','Caridade','Simplicidade','Devoção mariana']::TEXT[], ARRAY['Quem reza e trabalha não precisa de mais nada.','Confiem em Nossa Senhora','ela nunca abandona seus filhos.','A caridade é a maior de todas as virtudes.']::TEXT[]),
('maria-mae-deus', 'Santa Maria', 'Theotokos', '1 de Janeiro', 1, 1, 'Séc. I a.C.', 'Séc. I', ARRAY['Humanidade','Mães']::TEXT[], 'Mãe de Jesus Cristo', '', 'virgin', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg/440px-Sassoferrato_-_Jungfrun_i_b%C3%B6n_-_Google_Art_Project.jpg', '', ARRAY['Obediência','Pureza','Fé']::TEXT[], ARRAY['Eis a serva do Senhor','faça-se em mim segundo a tua palavra.']::TEXT[]),
('basilio-gregorio', 'São Basílio Magno e São Gregório Nazianzeno', 'Doutores da Igreja', '2 de Janeiro', 1, 2, '329/330', '379/390', ARRAY['Monges','Educadores']::TEXT[], 'Dois dos três Padres Capadócios', '', 'doctor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Sv_Vasilii_Velikii_%28765%29.jpg/440px-Sv_Vasilii_Velikii_%28765%29.jpg', '', ARRAY['Sabedoria','Caridade']::TEXT[], ARRAY['A Bíblia é a carta de Deus para a humanidade.']::TEXT[]),
('nome-jesus', 'Santíssimo Nome de Jesus', 'Nome acima de todo nome', '3 de Janeiro', 1, 3, '', '', ARRAY['Cristãos']::TEXT[], 'Festa que celebra o santo Nome de Jesus', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Bernardino_siena.jpg/440px-Bernardino_siena.jpg', '', ARRAY['Devoção']::TEXT[], ARRAY['Ao nome de Jesus se dobre todo joelho.']::TEXT[]),
('isabel-seton', 'Santa Isabel Ana Seton', 'Primeira Santa Americana', '4 de Janeiro', 1, 4, '1774', '1821', ARRAY['Viúvas','Escolas católicas']::TEXT[], 'Convertida ao catolicismo', '', 'founder', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Elizabeth_Ann_Seton.jpg/440px-Elizabeth_Ann_Seton.jpg', '', ARRAY['Caridade','Fé']::TEXT[], ARRAY['Vivam simplesmente para que outros possam simplesmente viver.']::TEXT[]),
('joao-neumann', 'São João Neumann', 'Bispo de Filadélfia', '5 de Janeiro', 1, 5, '1811', '1860', ARRAY['Educação católica']::TEXT[], 'Bispo redentorista que construiu dezenas de escolas e igrejas na Filadélfia.', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/St._John_Neumann.jpg/440px-St._John_Neumann.jpg', '', ARRAY['Zelo','Humildade']::TEXT[], ARRAY['Todo momento é um momento de graça.']::TEXT[]),
('epifania', 'Epifania do Senhor', 'Manifestação aos Gentios', '6 de Janeiro', 1, 6, '', '', ARRAY['Missionários']::TEXT[], 'Solenidade que celebra a visita dos Reis Magos ao Menino Jesus', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Adorazione_dei_Magi_-_Gentile_da_Fabriano.jpg/440px-Adorazione_dei_Magi_-_Gentile_da_Fabriano.jpg', '', ARRAY['Fé','Busca']::TEXT[], ARRAY['Viemos do Oriente para adorar o Rei.']::TEXT[]),
('raimundo-penafort', 'São Raimundo de Peñafort', 'Padroeiro dos Canonistas', '7 de Janeiro', 1, 7, '1175', '1275', ARRAY['Advogados','Canonistas']::TEXT[], 'Dominicano e grande jurista', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Ramon_de_Penyafort.jpg/440px-Ramon_de_Penyafort.jpg', '', ARRAY['Justiça','Sabedoria']::TEXT[], ARRAY['A justiça sem misericórdia é crueldade.']::TEXT[]),
('batismo-senhor', 'Batismo do Senhor', 'Início da Vida Pública', '13 de Janeiro', 1, 13, '', '', ARRAY['Catecúmenos']::TEXT[], 'Festa que celebra o batismo de Jesus no rio Jordão por João Batista', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Baptism-of-Christ-Pietro-Perugino.jpg/440px-Baptism-of-Christ-Pietro-Perugino.jpg', '', ARRAY['Humildade']::TEXT[], ARRAY['Tu és o meu Filho amado','em Ti me comprazo.']::TEXT[]),
('antonio-abade', 'Santo Antão do Deserto', 'Pai do Monaquismo', '17 de Janeiro', 1, 17, '251', '356', ARRAY['Eremitas','Animais']::TEXT[], 'Pai do monaquismo cristão', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Zurbaran_-_St._Anthony_the_Abbot.jpg/440px-Zurbaran_-_St._Anthony_the_Abbot.jpg', '', ARRAY['Ascese','Oração']::TEXT[], ARRAY['Vi todas as armadilhas do inimigo espalhadas pelo mundo e gemi: quem poderá escapar delas? Ouvi uma voz que me disse: A humildade.']::TEXT[]),
('sebastiao', 'São Sebastião', 'Mártir da Guarda Pretoriana', '20 de Janeiro', 1, 20, '256', '288', ARRAY['Soldados','Atletas','Rio de Janeiro']::TEXT[], 'Oficial romano que professava a fé cristã em segredo. Descoberto', '', 'martyr', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Andrea_Mantegna_089.jpg/440px-Andrea_Mantegna_089.jpg', '', ARRAY['Coragem','Fé']::TEXT[], ARRAY['A faith em Cristo é mais forte que qualquer flecha.']::TEXT[]),
('agnes', 'Santa Inês', 'Virgem e Mártir', '21 de Janeiro', 1, 21, '291', '304', ARRAY['Jovens','Noivas','Pureza']::TEXT[], 'Jovem romana que consagrou sua virgindade a Cristo e foi martirizada aos 12 anos durante a perseguição de Diocleciano.', '', 'virgin', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Jos%C3%A9_de_Ribera_064.jpg/440px-Jos%C3%A9_de_Ribera_064.jpg', '', ARRAY['Pureza','Coragem']::TEXT[], ARRAY['Já estou unida Àquele a quem os anjos servem.']::TEXT[]),
('conversao-paulo', 'Conversão de São Paulo', 'Apóstolo dos Gentios', '25 de Janeiro', 1, 25, '5 d.C.', '64/67', ARRAY['Missionários','Teólogos']::TEXT[], 'A conversão de Saulo de Tarso no caminho de Damasco é um dos eventos mais importantes do cristianismo.', '', 'apostle', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Caravaggio_-_La_conversione_di_San_Paolo.jpg/440px-Caravaggio_-_La_conversione_di_San_Paolo.jpg', '', ARRAY['Conversão','Zelo']::TEXT[], ARRAY['Já não sou eu quem vive','é Cristo que vive em mim.']::TEXT[]),
('brígida-irlanda', 'Santa Brígida da Irlanda', 'A Maria dos Gaélicos', '1 de Fevereiro', 2, 1, '451', '525', ARRAY['Irlanda','Poetas']::TEXT[], 'Uma das padroeiras da Irlanda', '', 'virgin', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/St_Brigid%27s_Cross.jpg/440px-St_Brigid%27s_Cross.jpg', '', ARRAY['Generosidade','Hospitalidade']::TEXT[], ARRAY['Cristo é visto em cada estranho.']::TEXT[]),
('apresentacao-senhor', 'Apresentação do Senhor', 'Candelária', '2 de Fevereiro', 2, 2, '', '', ARRAY['Vida consagrada']::TEXT[], 'Festa que celebra a apresentação de Jesus no Templo por Maria e José', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Andrea_Mantegna_049.jpg/440px-Andrea_Mantegna_049.jpg', '', ARRAY['Obediência','Esperança']::TEXT[], ARRAY['Os meus olhos viram a tua salvação.']::TEXT[]),
('bras', 'São Brás', 'Bispo e Mártir', '3 de Fevereiro', 2, 3, 'Séc. III', '316', ARRAY['Doenças de garganta']::TEXT[], 'Bispo e médico armênio', '', 'martyr', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Hans_Memling_-_St_Blaise_-_WGA15003.jpg/440px-Hans_Memling_-_St_Blaise_-_WGA15003.jpg', '', ARRAY['Cura','Compaixão']::TEXT[], ARRAY['A cura do corpo começa pela cura da alma.']::TEXT[]),
('agata', 'Santa Ágata', 'Virgem e Mártir', '5 de Fevereiro', 2, 5, 'Séc. III', '251', ARRAY['Bombeiros','Joalheiros','Catânia']::TEXT[], 'Jovem siciliana que resistiu aos avanços do prefeito Quintiano e foi horrivelmente torturada por sua fé.', '', 'virgin', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Francisco_de_Zurbar%C3%A1n_-_Saint_Agatha_-_Google_Art_Project.jpg/440px-Francisco_de_Zurbar%C3%A1n_-_Saint_Agatha_-_Google_Art_Project.jpg', '', ARRAY['Castidade','Fortaleza']::TEXT[], ARRAY['Senhor','que me criastes e me protegestes desde a infância.']::TEXT[]),
