('cirilo-metodio', 'Santos Cirilo e Metódio', 'Apóstolos dos Eslavos', '14 de Fevereiro', 2, 14, '826/827', '869/885', ARRAY['Europa','Eslavos']::TEXT[], 'Irmãos gregos que evangelizaram os povos eslavos. Cirilo criou o alfabeto glagolítico', '', 'confessor', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Slavonic_wenceslas_bible.jpg/440px-Slavonic_wenceslas_bible.jpg', '', ARRAY['Evangelização','Cultura']::TEXT[], ARRAY['A Palavra de Deus deve ser ouvida na língua de cada povo.']::TEXT[]),
('catedra-pedro', 'Cátedra de São Pedro', 'Pedra da Igreja', '22 de Fevereiro', 2, 22, '', '', ARRAY['Papado']::TEXT[], 'Festa que celebra a autoridade de ensino que Cristo confiou a Pedro e seus sucessores como chefe da Igreja.', '', 'apostle', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Cathedra_Petri_adjusted.JPG/440px-Cathedra_Petri_adjusted.JPG', '', ARRAY['Autoridade','Fé']::TEXT[], ARRAY['Tu és Pedro e sobre esta pedra edificarei a minha Igreja.']::TEXT[]),
